#define MAX_N 100

int n, m;
char grid[MAX_N][MAX_N + 1];
bool visited[MAX_N][MAX_N];

int dx[] = {-1, 1, 0, 0};
int dy[] = {0, 0, -1, 1};

void dfs(int x, int y, char material, int *min_x, int *max_x, int *min_y, int *max_y) {
    if (x < 0 || x >= n || y < 0 || y >= m) return;
    if (visited[x][y] || grid[x][y] != material) return;
    visited[x][y] = true;
    if (x < *min_x) *min_x = x;
    if (x > *max_x) *max_x = x;
    if (y < *min_y) *min_y = y;
    if (y > *max_y) *max_y = y;
    for (int i = 0; i < 4; i++) {
        dfs(x + dx[i], y + dy[i], material, min_x, max_x, min_y, max_y);
    }
}

