struct Point {
    int x, y;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int H, W;
    cin >> H >> W;

    vector<string> grid(H);
    for (int i = 0; i < H; ++i) {
        cin >> grid[i];
    }

    // Find all distinct materials (letters)
    set<char> materials;
    for (int i = 0; i < H; ++i) {
        for (int j = 0; j < W; ++j) {
            if (grid[i][j] != '.') {
                materials.insert(grid[i][j]);
            }
        }
    }

    // For each material, check if it forms a perfect rectangle
    for (char mat : materials) {
        int minX = W, maxX = -1, minY = H, maxY = -1;

        // Find bounding box
        for (int i = 0; i < H; ++i) {
            for (int j = 0; j < W; ++j) {
                if (grid[i][j] == mat) {
                    minX = min(minX, j);
                    maxX = max(maxX, j);
                    minY = min(minY, i);
                    maxY = max(maxY, i);
                }
            }
        }

        // Check if all cells in bounding box are this material
        bool isRectangular = true;
        for (int i = minY; i <= maxY && isRectangular; ++i) {
            for (int j = minX; j <= maxX && isRectangular; ++j) {
                if (grid[i][j] != mat) {
                    isRectangular = false;
                }
            }
        }

        // Also check for multiple disconnected components of same material
        // If not rectangular, it's suspicious
        if (!isRectangular) {
            cout << "SUSPICIOUS" << endl;
            return 0;
        }

        // Check if there is exactly one connected component
        vector<vector<bool>> visited(H, vector<bool>(W, false));
        int components = 0;

        for (int i = 0; i < H; ++i) {
            for (int j = 0; j < W; ++j) {
                if (grid[i][j] == mat && !visited[i][j]) {
                    components++;
                    if (components > 1) {
                        cout << "SUSPICIOUS" << endl;
                        return 0;
                    }

                    // BFS to mark component
                    queue<Point> q;
                    q.push({j, i});
                    visited[i][j] = true;

                    int dx[] = {0, 0, 1, -1};
                    int dy[] = {1, -1, 0, 0};

                    while (!q.empty()) {
                        Point p = q.front();
                        q.pop();

                        for (int d = 0; d < 4; ++d) {
                            int nx = p.x + dx[d];
                            int ny = p.y + dy[d];

                            if (nx >= 0 && nx < W && ny >= 0 && ny < H &&
                                grid[ny][nx] == mat && !visited[ny][nx]) {
                                visited[ny][nx] = true;
                                q.push({nx, ny});
                            }
                        }
                    }
                }
            }
        }
    }

    cout << "SAFE" << endl;
    return 0;
}

