            int cnt = 0;

            while (!q.empty()) {
                auto [x, y] = q.front();
                q.pop();
                cnt++;

                minR = min(minR, x);
                maxR = max(maxR, x);
                minC = min(minC, y);
                maxC = max(maxC, y);

                for (int k = 0; k < 4; ++k) {
