public class BaggageCheck {
    static int[] dr = {-1, 1, 0, 0};
    static int[] dc = {0, 0, -1, 1};

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int h = sc.nextInt();
        int w = sc.nextInt();
        sc.nextLine();
        char[][] grid = new char[h][w];
        for (int i = 0; i < h; i++) {
            String line = sc.nextLine();
            grid[i] = line.toCharArray();
        }

        boolean[][] visited = new boolean[h][w];

        for (int i = 0; i < h; i++) {
            for (int j = 0; j < w; j++) {
                if (grid[i][j] != '.' && !visited[i][j]) {
                    // BFS to find component
                    char letter = grid[i][j];
                    Queue<int[]> queue = new LinkedList<>();
                    queue.add(new int[]{i, j});
                    visited[i][j] = true;

                    int minR = i, maxR = i, minC = j, maxC = j;
                    List<int[]> cells = new ArrayList<>();
                    cells.add(new int[]{i, j});

                    while (!queue.isEmpty()) {
                        int[] cur = queue.poll();
                        int r = cur[0], c = cur[1];
                        for (int d = 0; d < 4; d++) {
                            int nr = r + dr[d];
                            int nc = c + dc[d];
                            if (nr >= 0 && nr < h && nc >= 0 && nc < w 
                                && !visited[nr][nc] && grid[nr][nc] == letter) {
                                visited[nr][nc] = true;
                                queue.add(new int[]{nr, nc});
                                cells.add(new int[]{nr, nc});
                                minR = Math.min(minR, nr);
                                maxR = Math.max(maxR, nr);
                                minC = Math.min(minC, nc);
                                maxC = Math.max(maxC, nc);
                            }
                        }
                    }

                    // check if rectangle
                    int expectedSize = (maxR - minR + 1) * (maxC - minC + 1);
                    if (cells.size() != expectedSize) {
                        System.out.println("SUSPICIOUS");
                        return;
                    }
                }
            }
        }
        System.out.println("SAFE");
    }
}

