                    int idx = c - 'A';
                    present[idx] = true;
                    if (i < minRow[idx]) minRow[idx] = i;
                    if (i > maxRow[idx]) maxRow[idx] = i;
                    if (j < minCol[idx]) minCol[idx] = j;
                    if (j > maxCol[idx]) maxCol[idx] = j;
                }
            }
        }

        // Check each letter's bounding box
        for (int idx = 0; idx < 26; idx++) {
