public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder out = new StringBuilder();

        while (true) {
            Integer hObj = fs.nextIntOrNull();
            if (hObj == null) break;
            int h = hObj;
            int w = fs.nextInt();

            if (h == 0 && w == 0) break;

            char[][] grid = new char[h][];
            for (int i = 0; i < h; i++) {
                grid[i] = fs.next().toCharArray();
            }

            boolean suspicious = false;

            for (char ch = 'A'; ch <= 'Z' && !suspicious; ch++) {
                int minR = h, maxR = -1, minC = w, maxC = -1;
                int count = 0;

                for (int r = 0; r < h; r++) {
                    for (int c = 0; c < w; c++) {
                        if (grid[r][c] == ch) {
                            count++;
                            if (r < minR) minR = r;
                            if (r > maxR) maxR = r;
                            if (c < minC) minC = c;
                            if (c > maxC) maxC = c;
                        }
                    }
                }

                if (count == 0) continue;

                int area = (maxR - minR + 1) * (maxC - minC + 1);
                if (area != count) {
                    suspicious = true;
                } else {
                    for (int r = minR; r <= maxR && !suspicious; r++) {
                        for (int c = minC; c <= maxC; c++) {
                            if (grid[r][c] != ch) {
                                suspicious = true;
                                break;
                            }
                        }
                    }
                }
            }

            out.append(suspicious ? "SUSPICIOUS" : "SAFE").append('\n');
        }

        System.out.print(out.toString());
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c != -1 && c <= ' ');
            while (c != -1 && c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        Integer nextIntOrNull() throws IOException {
            String s = next();
            if (s.isEmpty()) return null;
            return Integer.parseInt(s);
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

