import sys

def solve():
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return

    first = data[0].split()
    if len(first) == 2:
        r, c = map(int, first)
        grids = [data[1:1 + r]]
    else:
        t = int(first[0])
        grids = []
        idx = 1
        for _ in range(t):
            r, c = map(int, data[idx].split())
            idx += 1
            grids.append(data[idx:idx + r])
            idx += r

    out = []

    for grid in grids:
        pos = {}
        for i, row in enumerate(grid):
            for j, ch in enumerate(row):
                if ch != '.':
                    if ch not in pos:
                        pos[ch] = [i, i, j, j]  # minr, maxr, minc, maxc
                    else:
                        pos[ch][0] = min(pos[ch][0], i)
                        pos[ch][1] = max(pos[ch][1], i)
                        pos[ch][2] = min(pos[ch][2], j)
                        pos[ch][3] = max(pos[ch][3], j)

        suspicious = False

        for ch, (minr, maxr, minc, maxc) in pos.items():
            for i in range(minr, maxr + 1):
                row = grid[i]
                for j in range(minc, maxc + 1):
                    if row[j] != ch:
                        suspicious = True
                        break
                if suspicious:
                    break
            if suspicious:
                break

        out.append("SUSPICIOUS" if suspicious else "SAFE")

    sys.stdout.write("\n".join(out))

